const items = [
  { id: 1, name: 'Shift Jacket', price: 200, cat: 'outer', photo: 'print-jacket', width: 941, height: 1672, alt: 'Full-length model wearing an oversized white jacket with an abstract black print' },
  { id: 2, name: 'Contour Poncho', price: 300, cat: 'outer', photo: 'knit-cape', width: 1122, height: 1402, alt: 'Model wearing a cream open-knit poncho with fringe' },
  { id: 3, name: 'Diagonal Zip Hoodie', price: 100, cat: 'base', photo: 'knit-zip', width: 1122, height: 1402, alt: 'Grey zip hoodie with wide sleeves and a white radial pattern' },
  { id: 4, name: 'Split Trousers', price: 200, cat: 'bottom', photo: 'wrap-trousers', width: 950, height: 1656, alt: 'Wide black-and-white wrap trousers on a dress form in a studio' }
].map(p => ({ ...p, img: `assets/photos/${p.photo}.jpg` }));

function productPhoto(p, detail = false) {
  const srcset = `assets/photos/${p.photo}-480.jpg 480w, assets/photos/${p.photo}-800.jpg 800w, ${p.img} ${p.width}w`;
  const sizes = detail ? '(max-width: 800px) 80vw, 390px' : '(max-width: 800px) 45vw, 23vw';
  return `<img src="${p.img}" srcset="${srcset}" sizes="${sizes}" width="${p.width}" height="${p.height}" alt="${p.alt}" loading="${detail ? 'eager' : 'lazy'}" decoding="async">`;
}

const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);let cart=[];try{cart=JSON.parse(localStorage.getItem('asimetria-bag')||'[]')}catch{};const products=document.querySelector('#products');function render(filter='all'){products.innerHTML=items.filter(p=>filter==='all'||p.cat===filter).map(p=>`<button class="product" data-id="${p.id}" aria-label="View ${p.name}"><div class="product-image">${productPhoto(p)}<span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20 20 4M4 4h16v16"/></svg></span></div><div class="product-info">${p.name}<span>${money(p.price)}</span></div></button>`).join('')}render();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelector('.filters .active').classList.remove('active');b.classList.add('active');render(b.dataset.filter)});
const pd=document.querySelector('#productDialog'),bd=document.querySelector('#bagDialog');products.onclick=e=>{const b=e.target.closest('[data-id]');if(!b)return;const p=items.find(p=>p.id===+b.dataset.id);document.querySelector('#productContent').innerHTML=`<div class="detail">${productPhoto(p, true)}<div><h2>${p.name}</h2><p>${money(p.price)}</p><label>Choose your size</label><div class="sizes">${['XS','S','M','L'].map(s=>`<button type="button">${s}</button>`).join('')}</div><button class="primary" id="add">Add to bag</button><p><small>Demonstration product</small></p></div></div>`;let size=null;pd.querySelectorAll('.sizes button').forEach(b=>b.onclick=()=>{pd.querySelector('.selected')?.classList.remove('selected');b.classList.add('selected');size=b.textContent});pd.querySelector('#add').onclick=()=>{if(!size){toast('Please choose a size first');return}cart.push({id:p.id,size});save();pd.close();bag();bd.showModal();toast('Added to your bag')};pd.showModal()};
function save(){try{localStorage.setItem('asimetria-bag',JSON.stringify(cart))}catch{}document.querySelector('#count').textContent=`(${cart.length})`}save();function bag(){document.querySelector('#bagContent').innerHTML=cart.length?cart.map((x,i)=>{const p=items.find(p=>p.id===x.id);return `<div class="cart-row"><img src="${p.img}" alt="${p.name}"><div>${p.name}<small>Size ${x.size} / ${money(p.price)}</small></div><button data-remove="${i}" aria-label="Remove ${p.name}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 5 14 14M5 19 19 5"/></svg></button></div>`}).join('')+`<h3>Total: ${money(cart.reduce((t,x)=>t+items.find(p=>p.id===x.id).price,0))}</h3><a class="primary checkout" href="https://t.me/kiwnt1" target="_blank" rel="noopener noreferrer">Place an order <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20 20 4M4 4h16v16"/></svg></a><p class="checkout-note">Order via Telegram. Send the product name and your chosen size.</p>`:'<p>Your bag is empty. Find your shape in the collection.</p><button class="primary" id="toCatalog">Explore the collection</button>';document.querySelector('#toCatalog')?.addEventListener('click',()=>{bd.close();document.querySelector('#catalog').scrollIntoView({behavior:'smooth'})});bd.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(+b.dataset.remove,1);save();bag()})}document.querySelector('#bagButton').onclick=()=>{bag();bd.showModal()};document.querySelector('#infoButton').onclick=()=>document.querySelector('#infoDialog').showModal();document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});let toastTimer;function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
